import{R as i,e as t,f as o,U as s}from"./chunks/framework.ywem4qy5.js";const a="/assets/form-builder-create.lXIhNSsX.png",l="/assets/form-builder-multi-page.CVmFceM9.png",c=JSON.parse('{"title":"Form Builder","description":"","frontmatter":{},"headers":[],"relativePath":"forms/form-builder.md","filePath":"forms/form-builder.md","lastUpdated":1776231488000}'),r={name:"forms/form-builder.md"};function n(h,e,m,u,d,p){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="form-builder" tabindex="-1">Form Builder <a class="header-anchor" href="#form-builder" aria-label="Permalink to &quot;Form Builder&quot;">​</a></h1><p>The form builder is where most form work starts, and for most projects it is where the real shape of the form gets decided.</p><p>You use it to add pages and fields, but also to decide how the form should behave once it is live.</p><p><img src="'+a+'" alt="Fresh Formie form builder view"></p><h2 id="building-the-form" tabindex="-1">Building the form <a class="header-anchor" href="#building-the-form" aria-label="Permalink to &quot;Building the form&quot;">​</a></h2><p>At its simplest, the builder lets you:</p><ul><li>add fields to a page</li><li>arrange them into rows and columns</li><li>split a form into multiple pages</li><li>reuse existing fields</li><li>add synced fields when the same field should stay shared across forms</li></ul><p>For many forms, that is enough to get the structure in place. The more important decisions usually come from the settings that sit around the builder, because they affect how the form feels to the person filling it out.</p><h2 id="form-settings" tabindex="-1">Form settings <a class="header-anchor" href="#form-settings" aria-label="Permalink to &quot;Form settings&quot;">​</a></h2><p>Each form controls how submission feels on the front end.</p><p>The main choices are:</p><ul><li>whether the form submits with a page reload or Ajax</li><li>what should happen after a successful submission</li><li>where success and error messages should appear</li><li>whether validation should happen only on submit, or also while someone is moving through the form</li></ul><p>These settings matter most when they change the experience in a meaningful way. You will not need to tune every option on every form, but the ones that affect submission flow are worth knowing.</p><p>Forms can also decide who can submit and when.</p><p>Common examples are:</p><ul><li>requiring a logged-in user</li><li>opening or closing a form on a schedule</li><li>limiting how many submissions are allowed</li><li>showing a clear message when the form is unavailable</li></ul><p>This is the part of Formie that turns a form from a collection of fields into something a little more deliberate and controlled.</p><p>Form settings also control what a saved submission looks like and how long it is kept.</p><p>Important examples include:</p><ul><li>the default submission status</li><li>the submission title format</li><li>whether to collect the visitor IP address</li><li>whether to link the submission to a logged-in Craft user</li><li>how long to retain submission data</li><li>whether file uploads should be kept when a submission is removed</li></ul><p>These settings often end up being driven by policy rather than design, so it helps to check them early instead of leaving them until launch week.</p><h2 id="multi-page-forms" tabindex="-1">Multi-page forms <a class="header-anchor" href="#multi-page-forms" aria-label="Permalink to &quot;Multi-page forms&quot;">​</a></h2><p>Multi-page forms are not just a layout choice.</p><p><img src="'+l+'" alt="Multi-page form builder view"></p><p>They affect:</p><ul><li>page-to-page progress</li><li>incomplete submissions</li><li>save and continue later flows</li><li>conditions that skip pages entirely</li></ul><p>If the form uses multiple pages, also read <a href="/forms/save-continue-later">Save &amp; Continue Later</a> and <a href="/forms/conditions">Conditions</a>.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>The builder also includes a usage view so you can see where a form is being selected elsewhere in Craft.</p><p>That is especially helpful before changing or deleting a form, because it gives you a quick way to find entries or other elements that depend on it.</p>',30)])])}const g=i(r,[["render",n]]);export{c as __pageData,g as default};
